/**
 * @packages/contracts/archaeology
 * 
 * Formal interfaces for Infrastructure Reliability Archaeology.
 */

export interface ArchaeologySnapshot {
    id: string;
    timestamp: string;
    failureType: string;
    service: string;
    nodeVersion: string;
    os: string;
    arch: string;
    latencyMs: number;
    correlations: Record<string, any>;
    fingerprint: string;
}

export interface ArchaeologyIndex {
    version: string;
    snapshots: ArchaeologySnapshot[];
    metadata: {
        totalReplays: number;
        lastUpdated: string;
        recoveryStabilityScore: number;
    };
}

export interface EnvironmentStats {
    nodeVersions: Record<string, number>;
    os: Record<string, number>;
    arch: Record<string, number>;
}

export interface StabilityForecast {
    trend: 'IMPROVING' | 'DEGRADING' | 'STABLE';
    projectedVariance: number;
}

export interface RehearsalRequest {
    target: string;
    testSuite: string;
}

export interface RehearsalResponse {
    target: string;
    status: 'SUCCESS' | 'FAILURE';
    latencyMs: number;
    error?: string;
    timestamp: string;
}

/**
 * @packages/contracts/evidence-ledger
 * 
 * Formal Evidence and Causal Chain definitions for the Nexus ZTAN Replay Explorer.
 * This file establishes the deterministic invariants required for forensic replay.
 */

/**
 * Event Semantic Categories
 * Ensures that the Replay Engine can distinguish between telemetry, 
 * state changes, and autonomous heal actions.
 */
export enum EventCategory {
    MUTATION = 'mutation',      // Configuration change, deployment, pod restart
    OBSERVATION = 'observation', // Metric crossing threshold, health check failure
    DECISION = 'decision',     // Autonomous agent selecting a recovery strategy
    HEAL = 'heal',             // Execution of a recovery action
    GOVERNANCE = 'governance'  // Trust rotation, signature verification
}

/**
 * Causal Linkage
 * Enables the Replay Explorer to reconstruct the "Why" behind a state transition.
 */
export interface CausalLink {
    parentEventId: string;    // The immediate cause
    linkType: 'trigger' | 'dependency' | 'remediation';
    confidence: number;       // 0.0 to 1.0 (for AI-driven causality)
}

/**
 * Verification States
 * Defines the institutional trust level for a forensic chain or entry.
 */
export enum VerificationState {
    VERIFIED = 'verified',             // Full chain + valid signatures + current epoch
    DEGRADED = 'degraded',             // Chain valid, but some signatures from expired epochs
    UNTRUSTED = 'untrusted',           // Integrity hash mismatch or signature failure
    REVOKED = 'revoked',               // Signer was manually revoked for this period
    PARTIALLY_VERIFIED = 'partial'     // Root hash notarized, but local chain pending
}

/**
 * Trust Epoch
 * Defines a rotating institutional boundary for cryptographic authority.
 */
export interface TrustEpoch {
    id: string;                        // e.g., '2026-Q2-GOV-ROTATION-03'
    startTime: number;
    endTime?: number;                  // Null if active
    algorithm: 'ed25519' | 'ecdsa';
    status: 'active' | 'rotated' | 'compromised';
}

/**
 * Evidence Signature
 * The cryptographic proof of origin and authority.
 */
export interface EvidenceSignature {
    signerId: string;                  // ID of the operator or automated node
    algorithm: 'ed25519';
    signature: string;
    signedAt: number;
    trustEpochId: string;              // Pointer to the active TrustEpoch
    scope: 'entry' | 'checkpoint' | 'audit_root';
}

/**
 * Forensic Evidence Ledger Entry
 * The atomic unit of the Replay Engine. 
 * Designed for append-only, immutable storage.
 */
export interface EvidenceEntry {
    id: string;               // Unique UUID or Content-Addressable Hash
    timestamp: number;        // Deterministic Unix Epoch (Nanosecond precision)
    sequence: number;         // Monotonic incrementing counter within a shard/actor
    correlationId: string;    // Global trace/incident ID
    category: EventCategory;
    source: {
        service: string;
        node: string;
        version: string;
    };
    payload: Record<string, any>; // The raw state or delta
    causality?: CausalLink;   // Pointer to the cause
    
    /**
     * Integrity Metadata
     * Bound to the 'Stewardship' era for forensic trust.
     */
    integrity: {
        hash: string;         // SHA-256 of payload + timestamp + causality
        previousHash: string; // Hash of the previous sequence entry (Blockchain-style)
        signature?: EvidenceSignature; // Cryptographic attestation
        witnessId?: string;   // ID of the validator that certified this entry
        verificationState: VerificationState;
        tst?: any;            // RFC 3161 Time-Stamp Token
    };
}

/**
 * Replay Boundary Invariants
 * Defines the constraints for a deterministic replay session.
 */
export interface ReplayScope {
    startTime: number;
    endTime: number;
    targetNodes?: string[];
    targetServices?: string[];
    filterCategories?: EventCategory[];
}

/**
 * Evidence Chain
 * A collection of ordered, verified entries for a specific incident.
 */
export interface EvidenceChain {
    incidentId: string;
    rootCauseEntryId?: string;
    entries: EvidenceEntry[];
    verificationState: VerificationState;
    verificationEpoch: number;
    lastCheckpointId?: string;
    
    // Institutional Context
    governanceContext?: {
      id: string;
      quorum: string;
      notaryAnchor: string;
      authorityStatus: 'verified' | 'revoked' | 'degraded';
    };
    
    // Forensic Reliability
    metrics: ForensicResilienceMetrics;
}

/**
 * Ledger Checkpoint
 * A signed Merkle root of the entire ledger state for a specific epoch.
 * Used for external notarization and WORM compliance.
 */
export interface LedgerCheckpoint {
    id: string;
    timestamp: number;
    epochId: string;
    merkleRoot: string;               // Hash of all entries in this period
    count: number;
    signature: EvidenceSignature;     // Signed by the Notary Service
    externalReference?: string;       // e.g., KMS key version or external HSM proof
}

/**
 * Forensic Resilience Metrics
 * Measurable indices of institutional trust and operational survivability.
 */
export interface ForensicResilienceMetrics {
    chainIntegrityRate: number;       // % verified evidence continuity
    epochTrustValidity: number;       // Active authority health (0-1)
    replaySurvivability: number;      // Replay usability under degradation
    recoveryConfidence: number;       // Rollback trust score based on invariants
    evidenceCompleteness: number;     // Telemetry continuity score
    causalCertainty: number;          // Confidence in root-cause lineage
}

/**
 * @packages/contracts
 * 
 * Shared service contracts and ubiquitous language definitions.
 * This is the SOURCE OF TRUTH for cross-service communication.
 */

export * from './api.js';
export * from './sre.js';
export * from './archaeology.js';
export * from './evidence-ledger.js';
export * from './rollback-invariants.js';

export enum MissionStatus {
    PENDING = 'PENDING',
    RUNNING = 'RUNNING',
    COMPLETED = 'COMPLETED',
    FAILED = 'FAILED'
}

export enum ProjectStatus {
    DRAFT = 'DRAFT',
    ACTIVE = 'ACTIVE',
    ARCHIVED = 'ARCHIVED'
}

export interface ActivityInput {
  missionId: string;
  projectId: string;
  [key: string]: any;
}

export interface BuildActivityResult {
  success: boolean;
  artifactPath?: string;
  artifacts?: any[];
  duration?: number;
  error?: string;
}

export interface DeployActivityResult {
  success: boolean;
  url?: string;
  previewUrl?: string;
  error?: string;
}

export interface AgentRequest {
  prompt: string;
  context: AgentContext;
  params?: any;
}

export interface AgentResponse<T = any> {
  success: boolean;
  data: T;
  error?: string;
  metrics?: {
    tokensTotal: number;
    durationMs: number;
    confidence?: number;
  };
}

export interface AgentContext {
  executionId: string;
  projectId: string;
  metadata?: Record<string, any>;
}

/**
 * PROJECT DTO
 */
export interface Project {
  id: string;
  name: string;
  description?: string;
  status: ProjectStatus;
  createdAt: string | number;
  updatedAt: string | number;
  missionId?: string;
  userId?: string;
  tenantId?: string;
  files?: ProjectFile[];
}

export interface ProjectFile {
  path: string;
  content: string;
}

/**
 * MISSION DTO
 */
export interface MissionLifecycleUpdate {
  sequenceId: number;
  timestamp: number;
  clusterId: string;
  region: string;
  intent: string;
  prompt: string;
  status: MissionStatus | string;
  title?: string;
  executionId?: string;
  createdAt: string | number;
}

export interface Mission {
  id: string;
  projectId: string;
  userId: string;
  prompt: string;
  status: MissionStatus | string;
  title?: string;
  executionId?: string;
  createdAt: string | number;
  updatedAt?: string | number;
  tenantId?: string;
  metadata?: Record<string, any>;
}

export interface Chat {
  id: string;
  projectId: string;
  messages: Message[];
}


export interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: string;
}

// ΓöÇΓöÇ Compatibility Shims ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export type ProjectV1 = Project;
export type ProjectHistoryV1 = any;

export interface SREObserver {
  id: string;
  provider: string;
  weight: number;
  state: string;
  isCorrect: boolean;
  lastSeen?: string;
  reliabilityScore: number; // 0.0 - 1.0 (Time-series based)
  lastReliabilityUpdate: number; // Timestamp for decay calculations
  uptime: number; // Percentage
  actionPreference?: 'NO_ACTION' | 'ALERT' | 'ACT';
  group?: string; // NEW: For A/B group assignment in certification
}

export interface SREDiversity {
  providers: number;
  required: number;
  groups: string[];
  satisfied: boolean;
}

export interface SREDecomposition {
  quorum: number;
  diversity: number;
  stability: number;
}

export interface SREPerception {
  consensus: number;
  diversity: SREDiversity;
  weightedConfidence: number;
  decomposition: SREDecomposition;
  explainability: {
    rationale: string;
    impacts: { factor: string, score: number, delta: number }[];
  };
  expectedVariance: number; // Normal noise band
  anomalyHypothesis: {
    detected: boolean;
    zScore: number;
    confidence: number;
    type?: 'NOISE' | 'GRAY_FAILURE' | 'HARD_FAILURE' | 'STATISTICAL_OUTLIER' | 'NONE';
    precision?: number;
    recall?: number;
    f1?: number;
    support?: number;
  };
  brierScore: number; // Calibration Accuracy (lower is better)
  calibrationBuffer: number; // Safety uplift for threshold
  signalQuality: number; // 1.0 = Perfect, 0.0 = High Disorder
  signalIntegrityState: 'NOMINAL' | 'DEGRADED' | 'CRITICAL';
  causalCertainty: number; // Correlation between signal failure and anomaly
  wassersteinDistance: number; // p-distance for drift detection
  tuningVelocity: number; // Speed of threshold adaptation
  velocityDecay: number; // Rate of change of velocity (stability signal)
  convergenceState?: 'INITIALIZING' | 'CONVERGING' | 'OSCILLATING' | 'FORMALLY_STABLE';
  tuningHistory?: number[];
  wassersteinHistory?: number[];
}

export interface SREReliability {
  score: number;
  breakdown: {
    confidence: number;
    calibration: number;
    stability: number;
    consensus: number;
    dataQuality: number;
  };
}

export interface SREOperationalControl {
  mode: 'STABLE' | 'HEALING' | 'HALTED' | 'CHAOS_TEST' | 'AWAITING_APPROVAL' | 'SAFE_MODE';
  reason: string;
  reasonType: 'NO_QUORUM' | 'NO_DIVERSITY' | 'UNSTABLE_QUORUM' | 'LOW_CONFIDENCE' | 'POST_ACTION_DIVERGENCE' | 'SIGNAL_INTEGRITY_FAILURE' | 'NONE';
  holdTimeMs: number;
  expectedTTAC: number;
  slidingP95TTAC: number; // Dynamic p95 window
  reasoningDecomposition: {
    quorumContribution: number;
    diversityFactor: number;
    safetyBuffer: number;
    causalTrigger: string | null;
  };
  approvalRequired?: boolean;
  approvalRequestId?: string;
}

export interface SREEvent {
  time: string;
  type: string;
  desc: string;
  severity: 'INFO' | 'WARNING' | 'CRITICAL';
  evidenceId?: string; // Pointer to Evidence Ledger Entry
}

export interface SREUpdate {
  sequenceId: number; // Monotonic counter
  timestamp: number; // Unix ms
  clusterId?: string;
  region?: string;
  intent: string;
  perception?: SREPerception | any;
  operationalControl?: SREOperationalControl | any;
  observers?: SREObserver[] | any[];
  lastAction?: any;
  events?: SREEvent[] | any[];
  reliability?: SREReliability | any;
  topology?: {
    nodes: any[];
    edges: any[];
  };
  validation?: any;
  elite?: any;
  audit?: any;
  drift?: {
    dataDrift: number;
    conceptDrift: number;
    policyDrift: number;
    overallScore: number;
    status: 'NOMINAL' | 'DRIFTING' | 'CRITICAL';
  };
  learning?: {
    activeVersion: string;
    shadowVersion: string | null;
    isAdapting: boolean;
  };
  business?: {
    revenuePerMinute: number;
    activeUsers: number;
    impact: {
      revenueLossPerMin: number;
      projectedMonthlyLoss: number;
      riskLevel: string;
    };
    proposals: any[];
  };
  operationalAudit?: {
    avgBrier: number;
    avgRegret: number;
    avgRoiAccuracy: number;
    status: string;
    intervention: string;
  };
  stability?: {
    score: number;
  } | any;
  
  /**
   * Evidence Ledger Linkage
   * Connects this telemetry update to a verifiable forensic chain.
   */
  evidenceChainId?: string; // Correlation ID for the Evidence Ledger
}

export interface SRETuningParams {
  expectedTTAC: number;
  confidenceThreshold: number;
  reliabilityDecayRate: number;
  minDiversity: number;
}

import { History, CheckCircle2, XCircle, RotateCcw, Activity } from 'lucide-react';

interface AuditEvent {
    id: string;
    action: string;
    resource: string;
    status: 'SUCCESS' | 'FAILURE' | 'IN_PROGRESS' | 'ROLLED_BACK';
    timestamp: string;
    reason: string;
}

const EVENTS: AuditEvent[] = [
    { id: '1', action: 'K8S_ROLLOUT', resource: 'auth-api', status: 'SUCCESS', timestamp: '2 mins ago', reason: 'Security Patch v1.2.4' },
    { id: '2', action: 'INFRA_APPLY', resource: 'terraform/aws-us-east', status: 'FAILURE', timestamp: '15 mins ago', reason: 'Resource Quota Exceeded' },
    { id: '3', action: 'ROLLBACK', resource: 'terraform/aws-us-east', status: 'ROLLED_BACK', timestamp: '14 mins ago', reason: 'Automatic Auto-Recovery' },
    { id: '4', action: 'RECONCILE', resource: 'k8s:default/nginx', status: 'SUCCESS', timestamp: '1 hour ago', reason: 'Drift Repair' },
];

const AuditTimeline = () => {
    return (
        <div className="glass-panel h-full overflow-hidden flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-2">
                    <History className="text-blue-500" />
                    <h3 className="font-semibold uppercase tracking-tight text-sm">Evidence Timeline</h3>
                </div>
                <span className="text-[10px] bg-blue-500/10 text-blue-400 px-2 py-0.5 rounded-full font-bold">LIVE LEDGER</span>
            </div>

            <div className="space-y-6 overflow-y-auto pr-2 custom-scrollbar">
                {EVENTS.map((event) => (
                    <div key={event.id} className="relative pl-8 border-l border-white/5 pb-2">
                        <div className="absolute -left-[9px] top-0">
                            {event.status === 'SUCCESS' && <CheckCircle2 size={18} className="text-green-500 bg-black rounded-full" />}
                            {event.status === 'FAILURE' && <XCircle size={18} className="text-red-500 bg-black rounded-full" />}
                            {event.status === 'ROLLED_BACK' && <RotateCcw size={18} className="text-amber-500 bg-black rounded-full" />}
                            {event.status === 'IN_PROGRESS' && <Activity size={18} className="text-blue-500 animate-spin bg-black rounded-full" />}
                        </div>
                        
                        <div className="flex flex-col gap-1">
                            <div className="flex justify-between items-center">
                                <span className="text-xs font-mono font-bold text-white/80">{event.action}</span>
                                <span className="text-[10px] text-slate-500">{event.timestamp}</span>
                            </div>
                            <div className="text-[11px] text-blue-400 font-mono">{event.resource}</div>
                            <div className="text-[11px] text-slate-500 mt-1 italic">"{event.reason}"</div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default AuditTimeline;
